        uint before = token.balanceOf(from);
        // Execute transfer through C's transfer function, but we need to adapt: we replace caddress with token address
        // Since we cannot modify C, we must interpret caddress as token contract.
        // Use prank to impersonate from
        vm.prank(from);
        (bool ok,) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, address(token), _tos, v));
        vm.assume(ok);
        uint after = token.balanceOf(from);
        assertTrue(before - after == sum(v));
    }

    function sum(uint[] memory arr) internal pure returns (uint) {
        uint s = 0;
        for (uint i = 0; i < arr.length; i++) s += arr[i];
        return s;
    }
